import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"30、【离】 离下离上","description":"横渠易说 - 30、【离】 离下离上","frontmatter":{"title":"30、【离】 离下离上","description":"横渠易说 - 30、【离】 离下离上"},"headers":[],"relativePath":"zh/classics/hengqu/032.md","filePath":"zh/classics/hengqu/032.md"}'),l={name:"zh/classics/hengqu/032.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_30、【离】-离下离上" tabindex="-1">30、【离】 离下离上 <a class="header-anchor" href="#_30、【离】-离下离上" aria-label="Permalink to “30、【离】 离下离上”">​</a></h1><p>以柔丽乎中正，故利贞。</p><h3 id="彖曰-离-丽也-日月丽乎天-百谷草木丽乎土-重明以丽乎正-乃化成天下。柔丽乎中正故亨-是以畜牝牛吉也。" tabindex="-1">彖曰：离，丽也，日月丽乎天，百谷草木丽乎土，重明以丽乎正，乃化成天下。柔丽乎中正故亨，是以畜牝牛吉也。 <a class="header-anchor" href="#彖曰-离-丽也-日月丽乎天-百谷草木丽乎土-重明以丽乎正-乃化成天下。柔丽乎中正故亨-是以畜牝牛吉也。" aria-label="Permalink to “彖曰：离，丽也，日月丽乎天，百谷草木丽乎土，重明以丽乎正，乃化成天下。柔丽乎中正故亨，是以畜牝牛吉也。”">​</a></h3><p>日月草木丽天地，丽，附着也。</p><h3 id="象曰-明两作-离-大人以继明照于四方。" tabindex="-1">象曰：明两作，离，大人以继明照于四方。 <a class="header-anchor" href="#象曰-明两作-离-大人以继明照于四方。" aria-label="Permalink to “象曰：明两作，离，大人以继明照于四方。”">​</a></h3><p>明目达听，继明之道也。人患惰于博览，惟大人能勉而继之。</p><h3 id="初九-履错然-敬之-无咎。-象曰-履错之敬-以辟咎也。-履错然-与之者多也。无应于上-无所朋附-以刚处下-物所愿交-非矜慎之甚-何以免咎" tabindex="-1">初九，履错然，敬之，无咎。 象曰：履错之敬，以辟咎也。“履错然”，与之者多也。无应于上，无所朋附，以刚处下，物所愿交，非矜慎之甚，何以免咎! <a class="header-anchor" href="#初九-履错然-敬之-无咎。-象曰-履错之敬-以辟咎也。-履错然-与之者多也。无应于上-无所朋附-以刚处下-物所愿交-非矜慎之甚-何以免咎" aria-label="Permalink to “初九，履错然，敬之，无咎。 象曰：履错之敬，以辟咎也。“履错然”，与之者多也。无应于上，无所朋附，以刚处下，物所愿交，非矜慎之甚，何以免咎!”">​</a></h3><h3 id="六二-黄离-元吉。-象曰-黄离元吉-得中道也。" tabindex="-1">六二，黄离，元吉。 象曰：“黄离元吉”，得中道也。 <a class="header-anchor" href="#六二-黄离-元吉。-象曰-黄离元吉-得中道也。" aria-label="Permalink to “六二，黄离，元吉。 象曰：“黄离元吉”，得中道也。”">​</a></h3><h3 id="九三-日昃之离-不鼓缶而歌-则大耋之嗟-凶。-象曰-日昃之离-何可久也" tabindex="-1">九三，日昃之离，不鼓缶而歌，则大耋之嗟，凶。 象曰：日昃之离，何可久也! <a class="header-anchor" href="#九三-日昃之离-不鼓缶而歌-则大耋之嗟-凶。-象曰-日昃之离-何可久也" aria-label="Permalink to “九三，日昃之离，不鼓缶而歌，则大耋之嗟，凶。 象曰：日昃之离，何可久也!”">​</a></h3><p>明正将老，离过于中，故哀乐之不常其德，凡人不能久也。故君子为德，夭寿不贰。 人向衰暮则尤乐听声音，盖留连光景，视桑榆之暮景不足，则贪于为乐，惟郑卫之音能令人生此意。易谓“不鼓缶而歌则大耋之嗟凶”，悲衰暮故为乐，不为则复嗟年景之不足也。</p><h3 id="九四-突如其来如-焚如-死如-弃如。-象曰-突如其来如-无所容也。" tabindex="-1">九四，突如其来如，焚如，死如，弃如。 象曰：“突如其来如”，无所容也。 <a class="header-anchor" href="#九四-突如其来如-焚如-死如-弃如。-象曰-突如其来如-无所容也。" aria-label="Permalink to “九四，突如其来如，焚如，死如，弃如。 象曰：“突如其来如”，无所容也。”">​</a></h3><p>处多惧之地而以乘刚，故其来也遽，其处也危，无所容安，如见弃逐，皆所丽之失中也。三刚而 不可乘，五正而不见容。</p><h3 id="六五-出涕沱若-戚嗟若-吉。-象曰-六五之吉-离王公也。" tabindex="-1">六五，出涕沱若，戚嗟若，吉。 象曰：六五之吉，离王公也。 <a class="header-anchor" href="#六五-出涕沱若-戚嗟若-吉。-象曰-六五之吉-离王公也。" aria-label="Permalink to “六五，出涕沱若，戚嗟若，吉。 象曰：六五之吉，离王公也。”">​</a></h3><p>言王公之贵，人之所附，下以刚进，己虽忧危，终以得众而吉者，柔丽中正也。</p><h3 id="上九-王用出征-有嘉折首-获匪其丑-无咎。-象曰-王用出征-以正邦也。-有嘉折首-服而善之也。-获匪其丑-执讯弗宾-示威以正邦而已-离道已成-然后不附可征。" tabindex="-1">上九，王用出征，有嘉折首，获匪其丑，无咎。 象曰：“王用出征”，以正邦也。“有嘉折首”，服而善之也。“获匪其丑”，执讯弗宾，示威以正邦而已，离道已成，然后不附可征。 <a class="header-anchor" href="#上九-王用出征-有嘉折首-获匪其丑-无咎。-象曰-王用出征-以正邦也。-有嘉折首-服而善之也。-获匪其丑-执讯弗宾-示威以正邦而已-离道已成-然后不附可征。" aria-label="Permalink to “上九，王用出征，有嘉折首，获匪其丑，无咎。 象曰：“王用出征”，以正邦也。“有嘉折首”，服而善之也。“获匪其丑”，执讯弗宾，示威以正邦而已，离道已成，然后不附可征。”">​</a></h3>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
